import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import type { Circuit } from '../circuit/model';
import examples from '../examples/circuits.json';
import { densityOf } from './analysis';
import { finalState, probabilities, withReadout } from './simulator';

// Generated by reference/generate.py from Qiskit's Statevector, or DensityMatrix (with Qiskit Aer's noise channels)
// for dynamic and noisy circuits, already converted to Qanvas's bit order (q0 is the most significant bit of each index).
interface ReferenceCase {
  name: string;
  circuit: Circuit;
  state?: { re: number[]; im: number[] };
  density?: { re: number[]; im: number[] };
  probabilities?: number[];
}

const TOLERANCE = 1e-9;

function load(set: string): ReferenceCase[] {
  return JSON.parse(readFileSync(new URL(`../../reference/data/${set}.json`, import.meta.url), 'utf8'));
}

function maxDifference(actual: { re: ArrayLike<number>; im: ArrayLike<number> }, expected: { re: number[]; im: number[] }): number {
  expect(actual.re.length).toBe(expected.re.length);
  let max = 0;
  for (let i = 0; i < expected.re.length; i++) {
    max = Math.max(max, Math.abs(actual.re[i] - expected.re[i]), Math.abs(actual.im[i] - expected.im[i]));
  }
  return max;
}

describe.each(['single-gate', 'examples', 'random', 'mid-circuit'])('matches Qiskit: %s', (set) => {
  it.each(load(set))('$name', ({ circuit, state, density }) => {
    const actual = density ? densityOf(finalState(circuit)) : finalState(circuit);
    expect(maxDifference(actual, (density ?? state)!)).toBeLessThanOrEqual(TOLERANCE);
  });
});

it('has teleportation references for 15 input states', () => {
  expect(load('mid-circuit').filter((c) => c.name.startsWith('teleportation'))).toHaveLength(15);
});

it('has references for the current gallery circuits', () => {
  const references = Object.fromEntries(load('examples').map((c) => [c.name, c.circuit]));
  expect(references).toEqual(examples);
});

it('has 200 random circuits covering 1 to 12 qubits', () => {
  const random = load('random');
  expect(random).toHaveLength(200);
  expect(new Set(random.map((c) => c.circuit.qubits))).toEqual(new Set(Array.from({ length: 12 }, (_, i) => i + 1)));
});

describe('matches Qiskit with noise', () => {
  it.each(load('noise'))('$name', ({ circuit, density, probabilities: reported }) => {
    const state = finalState(circuit);
    expect(maxDifference(densityOf(state), density!)).toBeLessThanOrEqual(TOLERANCE);
    const p = withReadout(probabilities(state), circuit.qubits, circuit.noise?.readout ?? 0);
    expect(maxDifference({ re: p, im: new Float64Array(p.length) }, { re: reported!, im: new Array(p.length).fill(0) })).toBeLessThanOrEqual(TOLERANCE);
  });
});
